(() => {
  const form = document.querySelector('#australia-visa-form');
  if (!form) return;
  const type = document.querySelector('#australia-visa-type'), speed = document.querySelector('#australia-speed'), quantity = document.querySelector('#australia-quantity'), price = document.querySelector('#australia-price'), total = document.querySelector('#australia-total'), note = document.querySelector('#australia-speed-note'), docs = document.querySelector('#australia-documents'), feedback = document.querySelector('#australia-feedback'), submit = form.querySelector('[type="submit"]');
  const prices = { 'australia-visitor-600': 4100000, 'australia-transit-771': 500000 };
  const document = (key, label, required = false, icon = 'visa-document.png') => [key, label, required, '.pdf,.jpg,.jpeg,.png', icon];
  const standardDocuments = [document('face', 'Foto diri (tanpa kacamata)', true, 'visa-face.png'), document('passport', 'Halaman biodata paspor', true, 'visa-passport.png'), document('ticket', 'Tiket penerbangan', false, 'visa-ticket.png'), document('hotel', 'Bukti reservasi hotel', false, 'visa-hotel.png'), document('ktp', 'KTP', true), document('birth-certificate', 'Akta lahir', true), document('driving-license', 'SIM'), document('bank-mutation', 'Mutasi rekening koran 3 bulan terakhir'), document('bank-recommendation', 'Surat rekomendasi bank atau bank statement'), document('salary-slip', 'Slip gaji 3 bulan terakhir'), document('annual-tax-return', 'SPT tahunan'), document('leave-permit', 'Surat izin cuti bagi karyawan'), document('company-establishment', 'Surat pendirian perusahaan'), document('business-id', 'Nomor Induk Berusaha (NIB)'), document('current-passport-visa', 'Visa negara lain pada paspor saat ini'), document('previous-passport-visa', 'Visa negara lain pada paspor lama'), document('health-insurance', 'Asuransi kesehatan'), document('itinerary', 'Itinerary'), ...Array.from({ length: 10 }, (_, index) => document(`additional-${index + 1}`, `Dokumen tambahan ${index + 1}`))];
  const documentsForType = () => {
    const cards = standardDocuments.map(card => [...card]);
    if (type.value === 'australia-transit-771') {
      cards[2][2] = true; cards[3][2] = true;
      cards.splice(4, 0, document('destination-visa', 'Visa negara tujuan yang telah disetujui', true));
    }
    return cards;
  };
  const money = value => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
  const applicants = () => Math.min(10, Math.max(1, Number(quantity.value) || 1));
  const renderDocs = () => { const cards = documentsForType(); docs.innerHTML = Array.from({ length: applicants() }, (_, index) => `<details class="visa-applicant" ${index === 0 ? 'open' : ''}><summary><b>Pemohon ${index + 1} — Dokumen</b><span>0 file dipilih</span></summary><div class="visa-upload-grid">${cards.map(([key, label, required, accept, icon]) => `<label class="visa-document-card"><img class="visa-document-icon" src="/assets/${icon}" alt="" aria-hidden="true"><b>${label}${required ? ' *' : ''}</b><small>Klik untuk upload</small><input name="${key}_${index + 1}${key.startsWith('additional-') ? '[]' : ''}" type="file" ${required ? 'required' : ''} ${key.startsWith('additional-') ? 'multiple' : ''} accept="${accept}"></label>`).join('')}</div></details>`).join(''); docs.querySelectorAll('.visa-applicant').forEach(item => { item.addEventListener('change', () => { item.querySelector('summary span').textContent = `${[...item.querySelectorAll('input[type=file]')].reduce((sum, input) => sum + (input.files?.length || 0), 0)} file dipilih`; }); item.addEventListener('toggle', () => { if (item.open) docs.querySelectorAll('.visa-applicant[open]').forEach(other => { if (other !== item) other.open = false; }); }); }); };
  const refresh = () => { const ready = Boolean(type.value && speed.value), unit = ready ? prices[type.value] : 0; price.textContent = money(unit); total.textContent = money(unit * applicants()); note.textContent = speed.options[speed.selectedIndex].text; docs.hidden = !ready; submit.disabled = !ready; if (ready) renderDocs(); };
  [type, speed, quantity].forEach(control => control.addEventListener('input', refresh));
  window.addVisaAddressFields(form);
  form.querySelector('[name="phone"]').addEventListener('input', event => { event.target.value = event.target.value.replace(/\D/g, ''); });
  refresh();
  form.addEventListener('submit', async event => { event.preventDefault(); const data = new FormData(form); data.append('country', 'AU'); data.append('visaType', type.value); data.append('processingSpeed', speed.value); data.append('quantity', quantity.value); feedback.textContent = 'Mengirim aplikasi…'; try { const response = await fetch('/api/visa/create.php', { method: 'POST', body: data }); const result = await response.json(); if (!response.ok || !result.ok) throw new Error(result.message || 'Tidak dapat mengirim aplikasi.'); feedback.textContent = 'Aplikasi diterima.'; if (result.paymentUrl) location.href = result.paymentUrl; } catch (error) { feedback.textContent = error.message || 'Koneksi pembayaran belum tersedia. Silakan hubungi tim kami.'; } });
})();
